  function androidColorToCss(color) {
    if (!color) return "";
    if (/^#[0-9a-fA-F]{8}$/.test(color)) {
      const aa = color.slice(1, 3);
      const rrggbb = color.slice(3);
      return `#${rrggbb}${aa}`;
    }
    return color;
  }
  function decorationsFromActiveBackpack(activeDecorations) {
    const result = {};
    if (!Array.isArray(activeDecorations)) {
      return result;
    }
    for (const item of activeDecorations) {
      if (!item) continue;
      const expireAfter = Number(item.iea ?? 0);
      if (expireAfter <= 0) {
        continue;
      }
      const type = String(item.dt ?? "");
      if (!type) continue;
      result[type] = item.dp && typeof item.dp === "object" ? item.dp : {};
    }
    return result;
  }
