  // game/src/dialog/LoadingBox.ts
  function LoadingBox_default(options = {}) {
    const box = new Box({ title: options.title ?? "\u0417\u0410\u0413\u0420\u0423\u0417\u041A\u0410", canCloseAnywhere: options.canCloseAnywhere || false, height: 175 });
    const elem2 = document.createElement("div");
    elem2.style.width = "100%";
    elem2.style.height = "100%";
    elem2.style.padding = "15px 0 0 0";
    elem2.style.position = "absolute";
    elem2.style.display = "flex";
    elem2.style.flexDirection = "column";
    elem2.style.alignItems = "center";
    elem2.style.left = "0";
    box.content.appendChild(elem2);
    const loadingElem = document.createElement("img");
    fs_default.loadImageAsDataURL(`${App_default2.config.path}/assets/textures/loading/Tx.png`).then((e) => loadingElem.src = e);
    elem2.appendChild(loadingElem);
    const txt = document.createElement("p");
    txt.style.color = "black";
    txt.textContent = options.text ?? "";
    elem2.appendChild(txt);
    let rotation2 = 0;
    box.on("tick", (dt) => {
      if (dt % 2 < 1) return;
      loadingElem.style.transform = `rotateZ(${rotation2 % 360}deg)`;
      rotation2 += 30;
    });
    return {
      box,
      changeText(text2) {
        txt.textContent = text2;
      },
      done() {
        box.close();
      }
    };
  }

